BYTE* Image(DWORD pid,std::wstring const& path){auto s=CreateToolhelp32Snapshot(TH32CS_SNAPMODULE,pid);if(s==INVALID_HANDLE_VALUE)return nullptr;MODULEENTRY32W e{sizeof(e)};BYTE* p{};if(Module32FirstW(s,&e))do{if(_wcsicmp(e.szExePath,path.c_str())==0){p=e.modBaseAddr;break;}}while(Module32NextW(s,&e));CloseHandle(s);return p;}
DWORD Call(HANDLE p,BYTE* fn,const void* argument,size_t n){void* a=VirtualAllocEx(p,nullptr,n,MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE);if(!a)return GetLastError();if(!WriteProcessMemory(p,a,argument,n,nullptr))return GetLastError();auto t=CreateRemoteThread(p,nullptr,0,reinterpret_cast<LPTHREAD_START_ROUTINE>(fn),a,0,nullptr);if(!t)return GetLastError();if(WaitForSingleObject(t,6000)!=WAIT_OBJECT_0){CloseHandle(t);return ERROR_TIMEOUT;}DWORD result{};GetExitCodeThread(t,&result);CloseHandle(t);VirtualFreeEx(p,a,0,MEM_RELEASE);return result;}
int wmain(int argc,wchar_t** argv){if(argc!=3&&argc!=4)return 2;DWORD pid=wcstoul(argv[1],nullptr,10);std::wstring path=argv[2]; bool fixture=false;std::pair<DWORD,bool*> fixtureArgs{pid,&fixture}; EnumWindows([](HWND h,LPARAM data)->BOOL{auto a=reinterpret_cast<std::pair<DWORD,bool*>*>(data);DWORD target{};GetWindowThreadProcessId(h,&target);if(target==a->first&&GetPropW(h,L"Macdows.WindowStyler.Sample")){*a->second=true;return FALSE;}return TRUE;},reinterpret_cast<LPARAM>(&fixtureArgs));if(!fixture){std::wcerr<<L"Research loader accepts only marked fixtures.\n";return ERROR_NOT_SUPPORTED;}auto p=OpenProcess(PROCESS_CREATE_THREAD|PROCESS_QUERY_INFORMATION|PROCESS_VM_OPERATION|PROCESS_VM_WRITE|PROCESS_VM_READ,FALSE,pid);if(!p)return GetLastError();auto load=GetProcAddress(GetModuleHandleW(L"kernel32.dll"),"LoadLibraryW");HMODULE system{};GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS|GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,reinterpret_cast<LPCWSTR>(load),&system);wchar_t systemPath[32768]{};GetModuleFileNameW(system,systemPath,32768);auto remoteLoad=Image(pid,systemPath)+(reinterpret_cast<BYTE*>(load)-reinterpret_cast<BYTE*>(system));auto result=Call(p,remoteLoad,path.c_str(),(path.size()+1)*2);auto remote=Image(pid,path);if(!remote){CloseHandle(p);return result?result:126;}auto local=LoadLibraryExW(path.c_str(),nullptr,DONT_RESOLVE_DLL_REFERENCES);auto entry=GetProcAddress(local,argc==4?"StartExperiment":"StartReadOnly");if(!entry)return 127;DWORD dummy=argc==4?wcstoul(argv[3],nullptr,10):0;result=Call(p,remote+(reinterpret_cast<BYTE*>(entry)-reinterpret_cast<BYTE*>(local)),&dummy,sizeof(dummy));FreeLibrary(local);CloseHandle(p);std::wcout<<L"read-only diagnostics result="<<result<<L"\n";return result;}
